def resolve_origin(raw_origin: str) -> Optional[str]:
    """Map a free-text origin string to a canonical eligible origin, or None.

    Returns None for anything not in the eligible list -- including strings that
    are simply unparseable. None means "does not count toward regional content";
    callers surface unresolved strings to the human reviewer rather than dropping
    them, so an extraction slip shows up as a review flag instead of a quietly
    wrong percentage.

    Handles the realistic shapes an extraction step produces: a bare country
    name, an alias ("Ivory Coast"), and a city-qualified origin ("Tema, Ghana",
    "tanned Kano Nigeria").
    """
    parties = load_state_parties()
    canonical = {_normalise(_strip_accents(c)): c for c in parties["eligible_origins"]}
    aliases = {
        _normalise(_strip_accents(k)): v for k, v in parties.get("aliases", {}).items()
    }

    probe = _normalise(_strip_accents(raw_origin))
    if not probe:
        return None

    # 1. exact canonical name, then alias
    if probe in canonical:
        return canonical[probe]
    if probe in aliases:
        return aliases[probe]

    # 2. trailing comma-separated segment, e.g. "Tema, Ghana"
    if "," in probe:
        tail = probe.rsplit(",", 1)[-1].strip()
        if tail in canonical:
            return canonical[tail]
        if tail in aliases:
            return aliases[tail]

    # 3. exactly one eligible origin appears as a whole-word phrase in the string,
    #    e.g. "tanned Kano Nigeria". Ambiguous matches deliberately fall through to
    #    None so a human resolves them.
    hits = {
        name
        for key, name in {**canonical, **aliases}.items()
        if re.search(rf"(?<!\w){re.escape(key)}(?!\w)", probe)
    }
    if len(hits) == 1:
        return next(iter(hits))

    return None

